import React, {useState, useEffect, useCallback} from 'react';
import {useTranslation} from 'react-i18next';
import {CodeMirrorField} from './CodeMirrorField';

// Fetches properties AND checks module installation in one round-trip.
// Installation is detected via j:installedModules on the site node —
// the authoritative list maintained by Jahia when a module is installed/uninstalled.
const GQL_QUERY = `
    query getAddStuffProperties($sitePath: String!) {
        jcr {
            siteNode: nodeByPath(path: $sitePath) {
                installedModules: property(name: "j:installedModules") { values }
                addStuffHeadTop: property(name: "addStuffHeadTop") { value }
                addStuffHead:    property(name: "addStuffHead")    { value }
                addStuffBodyTop: property(name: "addStuffBodyTop") { value }
                addStuffBody:    property(name: "addStuffBody")    { value }
            }
        }
    }
`;

const GQL_MUTATION = `
    mutation setAddStuffProperties(
        $path: String!,
        $addStuffHeadTop: String!, $addStuffHead: String!,
        $addStuffBodyTop: String!, $addStuffBody: String!
    ) {
        jcr {
            mutateNode(pathOrId: $path) {
                addMixins(mixins: ["jmix:addStuff"])
                p1: mutateProperty(name: "addStuffHeadTop") { setValue(type: STRING, value: $addStuffHeadTop) }
                p2: mutateProperty(name: "addStuffHead")    { setValue(type: STRING, value: $addStuffHead) }
                p3: mutateProperty(name: "addStuffBodyTop") { setValue(type: STRING, value: $addStuffBodyTop) }
                p4: mutateProperty(name: "addStuffBody")    { setValue(type: STRING, value: $addStuffBody) }
            }
        }
    }
`;

function graphql(query, variables) {
    const contextPath = window.contextJsParameters.contextPath;
    return fetch(contextPath + '/modules/graphql', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'X-Requested-With': 'XMLHttpRequest'
        },
        credentials: 'include',
        body: JSON.stringify({query, variables})
    }).then(r => {
        if (!r.ok) {
            throw new Error('HTTP ' + r.status);
        }

        return r.json();
    });
}

const SECTION_STYLES = {
    border: '1px solid #ddd',
    borderRadius: '4px',
    marginBottom: '24px',
    overflow: 'hidden'
};

const HEADER_STYLES = {
    head: {
        fontFamily: 'monospace',
        fontSize: '13px',
        fontWeight: 'bold',
        padding: '8px 14px',
        background: '#e8f0fe',
        borderBottom: '1px solid #c5d4f5',
        color: '#2c5282'
    },
    body: {
        fontFamily: 'monospace',
        fontSize: '13px',
        fontWeight: 'bold',
        padding: '8px 14px',
        background: '#e6f4ea',
        borderBottom: '1px solid #b7dfc0',
        color: '#276534'
    }
};

const BODY_STYLES = {
    padding: '16px',
    background: '#f5f5f5',
    display: 'grid',
    gridTemplateColumns: '1fr 1fr',
    gap: '16px'
};

const LABEL_STYLES = {
    display: 'block',
    fontFamily: 'monospace',
    fontSize: '13px',
    fontWeight: 'bold',
    marginBottom: '4px'
};

const HELP_STYLES = {
    display: 'block',
    fontSize: '11px',
    color: '#aaa',
    margin: '2px 0 8px 0'
};

export function AddStuffSettings({siteKey}) {
    const {t} = useTranslation('addstuff');
    const sitePath = `/sites/${siteKey}`;

    const [installed, setInstalled] = useState(null); // null = loading, true/false = result
    const [values, setValues] = useState({
        addStuffHeadTop: '',
        addStuffHead: '',
        addStuffBodyTop: '',
        addStuffBody: ''
    });
    const [saving, setSaving] = useState(false);
    const [toast, setToast] = useState(null);

    useEffect(() => {
        graphql(GQL_QUERY, {sitePath})
            .then(data => {
                const jcr = data && data.data && data.data.jcr;
                const mods = jcr && jcr.siteNode && jcr.siteNode.installedModules && jcr.siteNode.installedModules.values;
                const isInstalled = Array.isArray(mods) && mods.some(m => m === 'addstuff' || m.startsWith('addstuff/'));
                setInstalled(isInstalled);
                if (isInstalled && jcr.siteNode) {
                    const n = jcr.siteNode;
                    setValues({
                        addStuffHeadTop: (n.addStuffHeadTop && n.addStuffHeadTop.value) || '',
                        addStuffHead:    (n.addStuffHead    && n.addStuffHead.value)    || '',
                        addStuffBodyTop: (n.addStuffBodyTop && n.addStuffBodyTop.value) || '',
                        addStuffBody:    (n.addStuffBody    && n.addStuffBody.value)    || ''
                    });
                }
            })
            .catch(() => setInstalled(false));
    }, [sitePath]);

    const handleSave = useCallback(() => {
        setSaving(true);
        graphql(GQL_MUTATION, {path: sitePath, ...values})
            .then(data => {
                if (data.errors && data.errors.length > 0) {
                    setToast({message: data.errors[0].message, error: true});
                } else {
                    setToast({message: t('addstuff.siteSettings.saved'), error: false});
                }
            })
            .catch(err => setToast({message: err.message, error: true}))
            .finally(() => setSaving(false));
    }, [sitePath, values, t]);

    const handleCancel = useCallback(() => {
        graphql(GQL_QUERY, {sitePath})
            .then(data => {
                const jcr = data && data.data && data.data.jcr;
                if (jcr && jcr.siteNode) {
                    const n = jcr.siteNode;
                    setValues({
                        addStuffHeadTop: (n.addStuffHeadTop && n.addStuffHeadTop.value) || '',
                        addStuffHead:    (n.addStuffHead    && n.addStuffHead.value)    || '',
                        addStuffBodyTop: (n.addStuffBodyTop && n.addStuffBodyTop.value) || '',
                        addStuffBody:    (n.addStuffBody    && n.addStuffBody.value)    || ''
                    });
                }
            });
    }, [sitePath]);

    useEffect(() => {
        if (toast) {
            const timer = setTimeout(() => setToast(null), 3000);
            return () => clearTimeout(timer);
        }
    }, [toast]);

    if (installed === null) {
        return null;
    }

    if (!installed) {
        return null;
    }

    return (
        <div style={{padding: '24px', maxWidth: '1400px'}}>
            <div className="page-header">
                <h2>{t('addstuff.siteSettings.title')}</h2>
            </div>
            <p style={{color: '#666', marginBottom: '24px'}}>{t('addstuff.siteSettings.description')}</p>

            {/* <head> section */}
            <div style={SECTION_STYLES}>
                <div style={HEADER_STYLES.head}>&lt;head&gt;</div>
                <div style={BODY_STYLES}>
                    <div>
                        <label style={LABEL_STYLES}>{t('jmix_addStuff.addStuffHeadTop')}</label>
                        <small style={HELP_STYLES}>{t('addstuff.siteSettings.headTop.help')}</small>
                        <CodeMirrorField
                            value={values.addStuffHeadTop}
                            onChange={v => setValues(prev => ({...prev, addStuffHeadTop: v}))}
                        />
                    </div>
                    <div>
                        <label style={LABEL_STYLES}>{t('jmix_addStuff.addStuffHead')}</label>
                        <small style={HELP_STYLES}>{t('addstuff.siteSettings.head.help')}</small>
                        <CodeMirrorField
                            value={values.addStuffHead}
                            onChange={v => setValues(prev => ({...prev, addStuffHead: v}))}
                        />
                    </div>
                </div>
            </div>

            {/* <body> section */}
            <div style={SECTION_STYLES}>
                <div style={HEADER_STYLES.body}>&lt;body&gt;</div>
                <div style={BODY_STYLES}>
                    <div>
                        <label style={LABEL_STYLES}>{t('jmix_addStuff.addStuffBodyTop')}</label>
                        <small style={HELP_STYLES}>{t('addstuff.siteSettings.bodyTop.help')}</small>
                        <CodeMirrorField
                            value={values.addStuffBodyTop}
                            onChange={v => setValues(prev => ({...prev, addStuffBodyTop: v}))}
                        />
                    </div>
                    <div>
                        <label style={LABEL_STYLES}>{t('jmix_addStuff.addStuffBody')}</label>
                        <small style={HELP_STYLES}>{t('addstuff.siteSettings.body.help')}</small>
                        <CodeMirrorField
                            value={values.addStuffBody}
                            onChange={v => setValues(prev => ({...prev, addStuffBody: v}))}
                        />
                    </div>
                </div>
            </div>

            {/* Actions */}
            <div style={{marginTop: '8px'}}>
                <button
                    className="btn btn-primary"
                    disabled={saving}
                    style={{marginRight: '8px'}}
                    onClick={handleSave}
                >
                    {t('label.save')}
                </button>
                <button
                    className="btn"
                    onClick={handleCancel}
                >
                    {t('label.cancel')}
                </button>
            </div>

            {toast && (
                <div style={{
                    position: 'fixed',
                    bottom: '24px',
                    right: '24px',
                    padding: '12px 20px',
                    borderRadius: '4px',
                    color: '#fff',
                    fontSize: '13px',
                    zIndex: 9999,
                    background: toast.error ? '#c0392b' : '#27ae60'
                }}>
                    {toast.message}
                </div>
            )}
        </div>
    );
}
